// Customer Audit Records Retrieval
// Fetches audit records for a customer within a date range

var customerId = input.get("customerId");
var startDate = input.get("startDate");
var endDate = input.get("endDate");
var accessToken = input.get("accessToken");

if (!customerId || customerId.trim() === "") {
    log.error("Customer ID is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Customer ID is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else if (!startDate || startDate.trim() === "") {
    log.error("Start Date is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Start Date is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else if (!endDate || endDate.trim() === "") {
    log.error("End Date is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "End Date is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else if (!accessToken || accessToken.trim() === "") {
    log.error("Access Token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access Token is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else {
    try {
        // Build the filter JSON
        var filter = json.stringify({
            Field: "CustomerId",
            Value: customerId.trim(),
            Operator: "equals"
        });

        // URL encode the parameters
        var encodedStartDate = encodeURIComponent(startDate.trim());
        var encodedEndDate = encodeURIComponent(endDate.trim());
        var encodedFilter = encodeURIComponent(filter);

        var url = "https://api.partnercenter.microsoft.com/v1/auditrecords?startDate=" + encodedStartDate + "&endDate=" + encodedEndDate + "&filter=" + encodedFilter;

        log.info("Fetching audit records for customer: " + customerId + " from " + startDate + " to " + endDate);

        var response = http.get(url, {
            "Authorization": "Bearer " + accessToken.trim(),
            "Accept": "application/json"
        });

        output.set("StatusCode", response.statusCode);
        output.set("Body", response.body);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            var data = json.parse(response.body);

            output.set("TotalCount", data.totalCount || 0);

            var items = data.items || [];
            output.set("ItemCount", items.length);

            output.set("HasErrors", false);
            output.set("ErrorMessage", "");

            log.info("Successfully retrieved " + items.length + " audit records");
            tags.trigger("success");
        } else {
            var errorMsg = "API returned status " + response.statusCode;
            try {
                var errorBody = json.parse(response.body);
                if (errorBody.message) errorMsg = errorBody.message;
                else if (errorBody.error_description) errorMsg = errorBody.error_description;
            } catch (e) {
                if (response.body) errorMsg = response.body.substring(0, 500);
            }

            log.error("Failed to retrieve audit records: " + errorMsg);
            output.set("HasErrors", true);
            output.set("ErrorMessage", errorMsg);
            output.set("TotalCount", 0);
            output.set("ItemCount", 0);
            tags.trigger("error");
        }
    } catch (ex) {
        log.error("Request failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Request failed: " + ex.message);
        output.set("StatusCode", 0);
        output.set("TotalCount", 0);
        output.set("ItemCount", 0);
        tags.trigger("error");
    }
}
